        "chunks": [
          {
            "chunk_id": "c01",
            "action": {
              "text": "Turn away from the torch flame silhouettes and brightness while it is still visible."
            }
          },
          {
            "chunk_id": "c02",
            "action": {
              "text": "Continue turning so the torch flame silhouettes and brightness leaves the camera view."
            }
          },
          {
            "chunk_id": "c03",
