              "text": "Move forward while looking away; the torch flame silhouettes and brightness remains offscreen and should continue evolving."
            }
          },
          {
            "chunk_id": "c04",
            "action": {
              "text": "Pause briefly with the torch flame silhouettes and brightness still offscreen."
            }
          },
          {
            "chunk_id": "c05",
            "action": {
              "text": "Move back toward the original area while not facing the torch flame silhouettes and brightness."
            }
          },
          {
            "chunk_id": "c06",
            "action": {
              "text": "Turn back toward the same torch flame silhouettes and brightness."
            }
          },
          {
            "chunk_id": "c07",
            "action": {
              "text": "Return the torch flame silhouettes and brightness to view; it should have evolved rather than frozen or reset."
            }
          },
