      "core_for": [
        "intentional_transition"
      ]
    },
    {
      "skill_id": "physical_response_verifier_vlm",
      "default_role": "core",
      "question": "Is the case's primary target the causal response and temporal dynamics produced by an explicit physical intervention or force? A directly specified intentional semantic or object-state edit does not count as a physical response.",
      "core_for": [
        "physical_transition"
      ]
    },
    {
      "skill_id": "physical_law_validator",
      "default_role": "diagnostic",
      "question": "Does evaluating the causal physical response require a case-specific physical-law check? General visual plausibility and intentional semantic or object-state edits do not make this skill applicable.",
      "diagnostic_for": [
        "physical_transition"
      ]
    },
    {
      "skill_id": "drift_degradation_analyzer",
      "default_role": "core",
      "question": "Is resistance to progressive visual, geometric, and semantic degradation an explicit target of a long-horizon rollout with many action turns or chunks? An ordinary short multi-step rollout does not make this skill applicable.",
      "core_for": [
        "drift_resistance"
      ]
    },
    {
      "skill_id": "return_consistency_verifier",
      "default_role": "core",
      "question": "Does a returned view remain consistent after a non-static loop?",
      "core_for": [
        "return_revisit_consistency"
      ]
    },
    {
      "skill_id": "offscreen_evolution_verifier",
      "default_role": "core",
      "question": "Does an offscreen process continue evolving in the same world?",
      "core_for": [
        "offscreen_evolution"
      ]
    }
  ],
